import { useState } from "react";
import { useAuth } from "../../context/AuthContext";

const demoMenu = [
  { id: 1, name: "Idli & Sambar", price: 35 },
  { id: 2, name: "Masala Dosa", price: 45 },
  { id: 3, name: "Veg Puff", price: 20 },
  { id: 4, name: "Veg Thali", price: 80 },
];

export default function UserPanel() {
  const { user, logout } = useAuth();
  const [cart, setCart] = useState([]);
  const [orders, setOrders] = useState([]);

  function addToCart(item) {
    const existing = cart.find((c) => c.id === item.id);
    if (existing) {
      setCart(
        cart.map((c) =>
          c.id === item.id ? { ...c, qty: c.qty + 1 } : c
        )
      );
    } else {
      setCart([...cart, { ...item, qty: 1 }]);
    }
  }

  function placeOrder() {
    if (cart.length === 0) return;

    const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
    const order = {
      id: "ORD" + (orders.length + 1),
      items: cart,
      total,
      status: "Preparing",
    };

    setOrders([order, ...orders]);
    setCart([]);
    alert("Demo Payment Successful. Order placed.");
  }

  return (
    <div className="app-shell">
      <header>
        <h2>User Panel</h2>
        <div>
          <span>{user.username}</span>
          <button className="btn btn-outline" onClick={logout}>
            Logout
          </button>
        </div>
      </header>

      <div className="card">
        <h3>Menu</h3>
        {demoMenu.map((item) => (
          <div key={item.id} className="menu-card">
            <span>{item.name}</span>
            <span>₹{item.price}</span>
            <button className="btn btn-primary btn-sm" onClick={() => addToCart(item)}>
              Add
            </button>
          </div>
        ))}
      </div>

      <div className="card">
        <h3>Cart</h3>
        {cart.length === 0 && <p>No items</p>}
        {cart.map((item) => (
          <div key={item.id}>
            {item.name} × {item.qty}
          </div>
        ))}
        <button className="btn btn-primary" onClick={placeOrder}>
          Place Order (Demo Payment)
        </button>
      </div>

      <div className="card">
        <h3>My Orders</h3>
        {orders.length === 0 && <p>No orders yet</p>}
        {orders.map((o) => (
          <div key={o.id}>
            {o.id} – ₹{o.total} – {o.status}
          </div>
        ))}
      </div>
    </div>
  );
}
